            if ((printMask?.Icons?.Overall ?? true)
                && item.Icons is {} IconsItem)
            {
                IconsItem?.Print(sb, "Icons");
            }
            if (printMask?.PickUpSound ?? true)
            {
                sb.AppendItem(item.PickUpSound.FormKeyNullable, "PickUpSound");
            }
            if (printMask?.DropSound ?? true)
            {
                sb.AppendItem(item.DropSound.FormKeyNullable, "DropSound");
            }
            if (printMask?.Type ?? true)
            {
                sb.AppendItem(item.Type, "Type");
            }
            if ((printMask?.Quests?.Overall ?? true)
                && item.Quests is {} QuestsItem)
            {
                sb.AppendLine("Quests =>");
                using (sb.Brace())
                {
                    foreach (var subItem in QuestsItem)
                    {
                        using (sb.Brace())
                        {
                            sb.AppendItem(subItem.FormKey);
                        }
                    }
                }
            }
            if ((printMask?.Texture ?? true)
                && item.Texture is {} TextureItem)
            {
                sb.AppendItem(TextureItem, "Texture");
            }
            if ((printMask?.TextOrTopic ?? true)
                && item.TextOrTopic is {} TextOrTopicItem)
            {
                sb.AppendLine($"TextOrTopic => {SpanExt.ToHexString(TextOrTopicItem)}");
            }
            if (printMask?.SoundOrNpc ?? true)
            {
                sb.AppendItem(item.SoundOrNpc.FormKeyNullable, "SoundOrNpc");
            }
        }
        
