        public static INoteGetter NoteFactory(
            OverlayStream stream,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            stream = Decompression.DecompressStream(stream);
            stream = ExtractRecordMemory(
                stream: stream,
                meta: package.MetaData.Constants,
                memoryPair: out var memoryPair,
                offset: out var offset,
                finalPos: out var finalPos);
            var ret = new NoteBinaryOverlay(
                memoryPair: memoryPair,
                package: package);
            ret._package.FormVersion = ret;
            ret.CustomFactoryEnd(
                stream: stream,
                finalPos: finalPos,
                offset: offset);
            ret.FillSubrecordTypes(
                majorReference: ret,
                stream: stream,
                finalPos: finalPos,
                offset: offset,
                translationParams: translationParams,
                fill: ret.FillRecordType);
            return ret;
        }

        public static INoteGetter NoteFactory(
            ReadOnlyMemorySlice<byte> slice,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            return NoteFactory(
                stream: new OverlayStream(slice, package),
                package: package,
                translationParams: translationParams);
        }

        public override ParseResult FillRecordType(
            OverlayStream stream,
            int finalPos,
            int offset,
            RecordType type,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            TypedParseParams translationParams = default)
        {
            type = translationParams.ConvertToStandard(type);
            switch (type.TypeInt)
            {
                case RecordTypeInts.OBND:
                {
                    _ObjectBoundsLocation = new RangeInt32((stream.Position - offset), finalPos - offset);
                    return (int)Note_FieldIndex.ObjectBounds;
                }
                case RecordTypeInts.FULL:
                {
                    _NameLocation = (stream.Position - offset);
                    return (int)Note_FieldIndex.Name;
                }
                case RecordTypeInts.MODL:
                case RecordTypeInts.MODB:
                case RecordTypeInts.MODT:
                case RecordTypeInts.MODS:
                case RecordTypeInts.MODD:
                {
                    this.Model = ModelBinaryOverlay.ModelFactory(
                        stream: stream,
                        package: _package,
                        translationParams: translationParams.DoNotShortCircuit());
                    return (int)Note_FieldIndex.Model;
                }
                case RecordTypeInts.ICON:
                {
                    this.Icons = IconsBinaryOverlay.IconsFactory(
                        stream: stream,
                        package: _package,
                        translationParams: translationParams.DoNotShortCircuit());
                    return (int)Note_FieldIndex.Icons;
                }
                case RecordTypeInts.YNAM:
                {
                    _PickUpSoundLocation = (stream.Position - offset);
                    return (int)Note_FieldIndex.PickUpSound;
                }
                case RecordTypeInts.ZNAM:
                {
                    _DropSoundLocation = (stream.Position - offset);
                    return (int)Note_FieldIndex.DropSound;
                }
                case RecordTypeInts.DATA:
                {
                    _TypeLocation = (stream.Position - offset);
                    return (int)Note_FieldIndex.Type;
                }
                case RecordTypeInts.ONAM:
                {
                    this.Quests = BinaryOverlayList.FactoryByStartIndexWithTrigger<IFormLinkGetter<IQuestGetter>>(
                        stream: stream,
                        package: _package,
                        finalPos: finalPos,
                        itemLength: 4,
                        getter: (s, p) => FormLinkBinaryTranslation.Instance.OverlayFactory<IQuestGetter>(p, s));
                    return (int)Note_FieldIndex.Quests;
                }
                case RecordTypeInts.XNAM:
                {
                    _TextureLocation = (stream.Position - offset);
                    return (int)Note_FieldIndex.Texture;
                }
                case RecordTypeInts.TNAM:
                {
                    _TextOrTopicLocation = (stream.Position - offset);
                    return (int)Note_FieldIndex.TextOrTopic;
                }
                case RecordTypeInts.SNAM:
                {
                    _SoundOrNpcLocation = (stream.Position - offset);
                    return (int)Note_FieldIndex.SoundOrNpc;
                }
                default:
                    return base.FillRecordType(
                        stream: stream,
                        finalPos: finalPos,
                        offset: offset,
                        type: type,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        translationParams: translationParams.WithNoConverter());
            }
        }
